<template><div class="page"><ProTable :columns="columns" :request-api="getSalaryLogPage" :dataCallback="dataCallback" row-key="id" title="工资修改日志" :tool-button="['refresh','setting','search']"><template #detail="scope"><el-button link type="primary" @click="show(scope.row)">查看差异</el-button></template></ProTable><el-dialog v-model="visible" title="工资修改详情" width="850px"><el-descriptions :column="1" border><el-descriptions-item label="差异"><pre>{{ diffText }}</pre></el-descriptions-item><el-descriptions-item label="修改前"><pre>{{ jsonText(current?.beforeData) }}</pre></el-descriptions-item><el-descriptions-item label="修改后"><pre>{{ jsonText(current?.afterData) }}</pre></el-descriptions-item></el-descriptions></el-dialog></div></template>
<script setup lang="ts">import { reactive,ref } from "vue";import ProTable from "@/components/ProTable/index.vue";import type { ColumnProps } from "@/components/ProTable/interface";import type { SalaryChangeLog } from "@/api/interface/hr";import { getSalaryLogPage } from "@/api/modules/hr";import { fieldLabels } from "../salary/fields";const visible=ref(false),current=ref<SalaryChangeLog>();const dataCallback=(d:any)=>({list:d.records,total:d.total});const parse=(v?:string)=>{try{return JSON.parse(v||"");}catch{return v||"";}};const jsonText=(v?:string)=>{const x=parse(v);return typeof x==="string"?x:JSON.stringify(x,null,2);};const diffText=ref("");const show=(row:SalaryChangeLog)=>{current.value=row;const x=parse(row.diffData);diffText.value=x&&typeof x==="object"?Object.entries(x).map(([k,v]:any)=>`${fieldLabels[k]||k}：${v?.before??v?.old??""} → ${v?.after??v?.new??""}`).join("\n"):String(x||"");visible.value=true;};const columns:ColumnProps[]=reactive([{type:"index",label:"序号",width:65},{label:"工资月份",prop:"salaryMonth",width:120,search:{el:"date-picker",props:{type:"month",valueFormat:"YYYY-MM"}}},{label:"工号",prop:"workNumber",width:100,search:{el:"input"}},{label:"姓名",prop:"staffName",width:120,search:{el:"input"}},{label:"修改原因",prop:"changeReason",minWidth:220},{label:"修改人",prop:"changeByName",width:120},{label:"修改时间",prop:"createTime",width:180},{label:"详情",prop:"detail",fixed:"right",width:100}]);</script><style scoped>.page{height:100%;min-height:0}pre{margin:0;white-space:pre-wrap;word-break:break-all}</style>
